export const GLOSSARY_FIELDS = ['Fundamentals', 'Deep learning', 'LLMs', 'Training', 'Inference', 'RAG', 'Agents', 'Protocols', 'Evaluation', 'Safety and MLOps'] as const;

export type GlossaryField = (typeof GLOSSARY_FIELDS)[number];

export interface GlossaryTerm {
  slug: string;
  term: string;
  field: GlossaryField;
  oneLine: string;
  explanation: string;
  example: string;
  confusedWith: string;
  learnPath: `/docs/${string}`;
  diagram: string;
}

const t = (slug: string, term: string, field: GlossaryField, oneLine: string, explanation: string, example: string, confusedWith: string, learnPath: `/docs/${string}`): GlossaryTerm => ({ slug, term, field, oneLine, explanation, example, confusedWith, learnPath, diagram: `glossary-${slug}` });

export const glossaryTerms: GlossaryTerm[] = [
  t('feature', 'Feature', 'Fundamentals', 'A feature is a measurable input supplied to a model.', 'Features turn raw observations into values a model can use. Their representation determines which patterns are easy for the model to learn.', 'Illustrative: a house model receives 1,400 ft², 3 bedrooms, and age 12 years.', 'Label: a feature is an input; a label is the target output.', '/docs/machine-learning/ml-workflow-fundamentals'),
  t('label', 'Label', 'Fundamentals', 'A label is the target value a supervised model learns to predict.', 'Training compares a prediction with its label to calculate error. Labels may be classes, numbers, sequences, or structured objects.', 'Illustrative: for an email, the label is spam = 1 while 42 token counts are features.', 'Feature: a label is the answer; a feature is evidence used to infer it.', '/docs/machine-learning/ml-workflow-fundamentals'),
  t('parameter', 'Parameter', 'Fundamentals', 'A parameter is a learned numeric value inside a model.', 'Optimization changes parameters to reduce loss. Weights and biases are parameters because training estimates them from data.', 'Illustrative: a 3-input linear layer with 2 outputs has 3×2 weights plus 2 biases, or 8 parameters.', 'Hyperparameter: parameters are learned; hyperparameters are chosen before or around training.', '/docs/machine-learning/ml-workflow-fundamentals'),
  t('hyperparameter', 'Hyperparameter', 'Fundamentals', 'A hyperparameter is a setting that controls model structure or training.', 'The training algorithm does not directly learn hyperparameters as model weights. Teams choose them through reasoning, sweeps, or optimization studies.', 'Illustrative: compare learning rates 0.001, 0.0003, and 0.0001 over three runs.', 'Parameter: a hyperparameter configures learning; a parameter is produced by learning.', '/docs/deep-learning/training-deep-networks'),
  t('supervised-learning', 'Supervised learning', 'Fundamentals', 'Supervised learning fits a mapping from inputs to known target outputs.', 'Each training example pairs evidence with an answer. The model generalizes that mapping to unseen inputs after minimizing prediction error.', 'Illustrative: train on 80,000 labeled images and evaluate on 10,000 held-out images.', 'Unsupervised learning: supervised data has explicit targets; unsupervised data does not.', '/docs/machine-learning/ml-workflow-fundamentals'),
  t('unsupervised-learning', 'Unsupervised learning', 'Fundamentals', 'Unsupervised learning finds structure in data without supplied target labels.', 'The objective may group examples, compress them, or estimate their distribution. The result is useful structure rather than a direct answer key.', 'Illustrative: cluster 12,000 customer vectors into k = 8 groups.', 'Self-supervised learning: self-supervision constructs targets from the data itself.', '/docs/machine-learning/unsupervised-learning'),
  t('classification', 'Classification', 'Fundamentals', 'Classification predicts one or more discrete categories.', 'A classifier produces scores or probabilities for a fixed label set. A decision rule then maps those values to class predictions.', 'Illustrative: probabilities cat 0.72, dog 0.21, fox 0.07 produce cat.', 'Regression: classification predicts categories; regression predicts continuous quantities.', '/docs/machine-learning/logistic-regression'),
  t('regression', 'Regression', 'Fundamentals', 'Regression predicts a continuous numeric quantity.', 'A regression model learns how inputs shift a numeric target. Its errors retain magnitude, so missing by 20 usually matters more than missing by 2.', 'Illustrative: a model predicts 18.4 minutes for a trip whose observed time is 20.0 minutes.', 'Classification: regression outputs a quantity; classification selects a category.', '/docs/machine-learning/linear-regression'),
  t('gradient-descent', 'Gradient descent', 'Fundamentals', 'Gradient descent updates parameters in the direction that reduces loss.', 'The gradient gives the local slope of the objective with respect to each parameter. The learning rate scales how far the optimizer moves.', 'Illustrative: with gradient 0.8 and learning rate 0.1, a weight moves from 2.0 to 1.92.', 'Backpropagation: backpropagation computes gradients; gradient descent uses them to update parameters.', '/docs/deep-learning/optimizers'),
  t('bias-variance-tradeoff', 'Bias-variance tradeoff', 'Fundamentals', 'The bias-variance tradeoff balances systematic underfitting against sensitivity to training data.', 'A model that is too rigid misses real structure, while one that is too flexible can fit sample noise. Validation performance reveals the useful middle region.', 'Illustrative: degree 1 underfits 40 points, degree 14 fits training noise, and degree 4 gives the lowest validation error.', 'Fairness bias: statistical bias is systematic estimation error, not social or demographic unfairness.', '/docs/machine-learning/model-evaluation-metrics'),

  t('neuron', 'Artificial neuron', 'Deep learning', 'An artificial neuron applies a weighted sum followed by an activation function.', 'The weighted sum combines evidence from several inputs. The activation introduces a nonlinear response that lets stacked layers model complex functions.', 'Illustrative: inputs [2, 1], weights [0.5, -0.25], and bias 0.1 give pre-activation 0.85.', 'Perceptron: a perceptron usually includes a hard threshold; modern neurons use differentiable activations.', '/docs/deep-learning/neural-network-fundamentals'),
  t('activation-function', 'Activation function', 'Deep learning', 'An activation function transforms a neuron’s pre-activation value.', 'Without nonlinear activations, many stacked linear layers collapse into one linear transformation. ReLU, GELU, and sigmoid create different gradient and output behavior.', 'Illustrative: ReLU maps [-2, 0.5, 3] to [0, 0.5, 3].', 'Loss function: activation shapes internal signals; loss scores final prediction error.', '/docs/deep-learning/activation-functions'),
  t('backpropagation', 'Backpropagation', 'Deep learning', 'Backpropagation applies the chain rule to compute gradients through a computation graph.', 'It moves from the loss toward earlier operations while reusing intermediate derivatives. The result is one gradient for every trainable parameter.', 'Illustrative: if dy/dh = 3 and dh/dw = 0.4, then dy/dw = 1.2.', 'Gradient descent: backpropagation computes gradients; gradient descent applies updates.', '/docs/deep-learning/training-deep-networks'),
  t('convolution', 'Convolution', 'Deep learning', 'A convolution slides a shared filter across local regions of an input.', 'Weight sharing lets one detector recognize the same pattern at different positions. Local connectivity also uses fewer parameters than a dense layer over the full image.', 'Illustrative: a 3×3 filter over a 32×32 image with valid padding produces a 30×30 map.', 'Pooling: convolution learns filters; pooling summarizes nearby values without learned kernels.', '/docs/deep-learning/cnns'),
  t('receptive-field', 'Receptive field', 'Deep learning', 'A receptive field is the input region that can influence one feature value.', 'Deeper convolutional layers combine information across progressively larger regions. Kernel size, stride, dilation, and depth determine its extent.', 'Illustrative: two stride-1 3×3 convolutions give a 5×5 receptive field.', 'Kernel: a kernel is the learned filter; the receptive field is the covered input region.', '/docs/deep-learning/cnns'),
  t('embedding', 'Embedding', 'Deep learning', 'An embedding maps a discrete item to a learned dense vector.', 'Training arranges vectors so useful relationships become accessible through geometry. Tokens, products, users, and graph nodes can all receive embeddings.', 'Illustrative: token 418 maps to a 768-value vector; two related vectors have cosine similarity 0.82.', 'One-hot encoding: one-hot vectors are fixed and sparse; embeddings are learned and dense.', '/docs/nlp/word-embeddings'),
  t('residual-connection', 'Residual connection', 'Deep learning', 'A residual connection adds a block’s input to its transformed output.', 'The identity path lets information and gradients bypass a difficult transformation. This makes very deep networks easier to optimize.', 'Illustrative: input [1.0, 2.0] plus block output [0.2, -0.3] gives [1.2, 1.7].', 'Dense connection: residual paths add tensors; dense connections concatenate features.', '/docs/deep-learning/advanced-architectures'),
  t('normalization', 'Normalization layer', 'Deep learning', 'A normalization layer rescales activations using statistics over selected dimensions.', 'Normalization keeps signal scales controlled and changes optimization geometry. Layer normalization is common in transformers because it works independently per sequence item.', 'Illustrative: values [2, 4, 6] become approximately [-1.22, 0, 1.22] before learned scale and shift.', 'Data normalization: a layer normalizes internal activations; data normalization preprocesses inputs.', '/docs/deep-learning/nn-layers-reference'),
  t('dropout', 'Dropout', 'Deep learning', 'Dropout randomly masks activations during training to reduce co-adaptation.', 'Each training step samples a different thinned network. At inference, dropout is disabled and scaling preserves the expected activation.', 'Illustrative: dropout p = 0.2 masks about 200 of 1,000 activations per training pass in expectation.', 'Pruning: dropout is temporary training noise; pruning permanently removes parameters or structures.', '/docs/deep-learning/initialization-regularization-scheduling'),
  t('autoencoder', 'Autoencoder', 'Deep learning', 'An autoencoder learns to reconstruct an input through a constrained latent representation.', 'The encoder compresses the input and the decoder rebuilds it. The constraint encourages the latent code to retain useful structure rather than copy every value directly.', 'Illustrative: compress 784 image pixels into 32 latent values, then reconstruct 784 pixels.', 'Variational autoencoder: a basic autoencoder maps to a point; a VAE learns a latent distribution.', '/docs/deep-learning/autoencoders'),

  t('token', 'Token', 'LLMs', 'A token is one unit in the sequence processed by a language model.', 'A tokenizer converts text into integer token identifiers before model computation. Tokens may be words, word pieces, punctuation, or bytes.', 'Illustrative: “unbelievable” might split into 3 tokens, depending on the tokenizer.', 'Word: a token is a model unit and does not necessarily match a linguistic word.', '/docs/llms-genai/foundation-model-internals'),
  t('tokenization', 'Tokenization', 'LLMs', 'Tokenization converts text into a sequence of vocabulary identifiers.', 'The tokenizer defines the model’s input alphabet and how text length translates into compute. Its segmentation choices affect multilingual coverage and rare strings.', 'Illustrative: a 12-character identifier can become 1 token or 8 tokens under different vocabularies.', 'Embedding: tokenization chooses IDs; embedding lookup converts those IDs into vectors.', '/docs/llms-genai/foundation-model-internals'),
  t('self-attention', 'Self-attention', 'LLMs', 'Self-attention mixes information among positions in the same sequence.', 'Each position scores other positions using query-key similarity and combines their value vectors. The learned weights make the context-dependent mixture explicit.', 'Illustrative: one token assigns weights [0.05, 0.15, 0.70, 0.10] across four positions.', 'Cross-attention: self-attention reads the same sequence; cross-attention reads another sequence or modality.', '/docs/deep-learning/attention-transformers'),
  t('causal-mask', 'Causal mask', 'LLMs', 'A causal mask prevents a decoder token from attending to future tokens.', 'The mask sets forbidden attention logits to negative infinity before softmax. Each position can therefore depend only on itself and earlier positions.', 'Illustrative: position 3 in a 5-token sequence can read positions 1 to 3 but not 4 or 5.', 'Padding mask: a causal mask blocks the future; a padding mask blocks non-content positions.', '/docs/deep-learning/attention-transformers'),
  t('multi-head-attention', 'Multi-head attention', 'LLMs', 'Multi-head attention runs several learned attention projections in parallel.', 'Each head can represent a different relation in its own projected subspace. The head outputs are concatenated and projected back to the model width.', 'Illustrative: width 768 split across 12 heads gives 64 dimensions per head.', 'Multi-query attention: multi-head attention has separate key-value heads; MQA shares one key-value head.', '/docs/deep-learning/attention-transformers'),
  t('transformer', 'Transformer', 'LLMs', 'A transformer is a sequence architecture built around attention and position-wise feed-forward blocks.', 'Attention exchanges information across positions, while feed-forward layers transform each position. Residual paths and normalization stabilize the stack.', 'Illustrative: 24 blocks process a sequence of 2,048 tokens at model width 2,048.', 'RNN: a transformer processes attention relationships directly; an RNN carries a recurrent state step by step.', '/docs/deep-learning/attention-transformers'),
  t('context-window', 'Context window', 'LLMs', 'A context window is the maximum token span available to one model invocation.', 'Prompt tokens, retrieved text, tool outputs, and generated tokens compete for this finite budget. Exceeding it requires truncation, compaction, or another request.', 'Illustrative: a 32,768-token window with 28,000 input tokens leaves at most 4,768 tokens for output.', 'Knowledge cutoff: context window is per-request capacity; knowledge cutoff is the date boundary of training knowledge.', '/docs/context-engineering/token-budgeting-and-compaction'),
  t('next-token-prediction', 'Next-token prediction', 'LLMs', 'Next-token prediction estimates a probability distribution for the token after a prefix.', 'Autoregressive language models repeat this operation to generate a sequence. Training uses the known next token at every position as the target.', 'Illustrative: after “2 + 2 =”, probabilities may assign 0.96 to token “4”.', 'Masked language modeling: next-token prediction is causal; masked modeling reconstructs hidden tokens using both sides.', '/docs/llms-genai/foundation-model-internals'),
  t('temperature', 'Temperature', 'LLMs', 'Temperature rescales logits before sampling to control distribution sharpness.', 'Lower temperature concentrates probability on high-logit tokens, while higher temperature spreads probability more broadly. A value of zero is commonly implemented as greedy selection rather than literal division.', 'Illustrative: logits [2, 1] yield probabilities about [0.73, 0.27] at temperature 1 and [0.88, 0.12] at 0.5.', 'Top-p: temperature reshapes all logits; top-p truncates to a cumulative probability mass.', '/docs/llms-genai/prompt-engineering'),
  t('hallucination', 'Hallucination', 'LLMs', 'A hallucination is a fluent model output that is unsupported or false in the relevant context.', 'Language-model likelihood rewards plausible continuation, not factual verification. Grounding, tools, constraints, and evaluation reduce risk but do not eliminate it.', 'Illustrative: a model invents a paper title and DOI when the retrieval result contains no such source.', 'Confabulation in humans: model hallucination describes unsupported output, not a claim about human cognition.', '/docs/ai-evaluation/llm-rag-agent-evaluation'),

  t('loss-function', 'Loss function', 'Training', 'A loss function converts prediction error into a scalar training objective.', 'Optimization follows the loss gradient, so the loss defines what behavior training rewards. Different losses encode different assumptions about errors.', 'Illustrative: predicted class probability 0.8 gives cross-entropy loss -ln(0.8) ≈ 0.223.', 'Metric: loss drives parameter updates; a metric reports behavior for interpretation.', '/docs/deep-learning/loss-functions'),
  t('learning-rate', 'Learning rate', 'Training', 'The learning rate scales each optimizer update.', 'A rate that is too large can overshoot useful regions, while a rate that is too small wastes steps. Schedules often change it over the run.', 'Illustrative: gradient 0.04 with learning rate 0.001 changes a parameter by 0.00004.', 'Batch size: learning rate controls step magnitude; batch size controls examples per gradient estimate.', '/docs/deep-learning/optimizers'),
  t('batch-size', 'Batch size', 'Training', 'Batch size is the number of examples used to estimate one gradient update.', 'Larger batches reduce gradient noise and increase memory demand. Smaller batches produce noisier updates and more optimizer steps per epoch.', 'Illustrative: 96,000 examples with batch size 192 produce 500 steps per epoch.', 'Epoch: batch size counts examples per update; an epoch covers the training set once.', '/docs/deep-learning/training-deep-networks'),
  t('epoch', 'Epoch', 'Training', 'An epoch is one pass through the training dataset.', 'Epochs are a data-coverage unit, not a fixed amount of compute across datasets. Shuffling changes which examples share a batch on each pass.', 'Illustrative: 1.2 million examples at batch size 1,200 make 1,000 optimizer steps per epoch.', 'Step: a step is one parameter update; an epoch contains many steps.', '/docs/deep-learning/training-deep-networks'),
  t('overfitting', 'Overfitting', 'Training', 'Overfitting occurs when a model learns training-specific detail that does not generalize.', 'Training error can keep falling after validation error begins to rise. Regularization, more representative data, or earlier stopping can reduce the gap.', 'Illustrative: training loss falls from 0.30 to 0.08 while validation loss rises from 0.34 to 0.51.', 'Underfitting: overfitting has a large train-validation gap; underfitting performs poorly on both.', '/docs/machine-learning/model-evaluation-metrics'),
  t('regularization', 'Regularization', 'Training', 'Regularization changes training to discourage brittle or overly complex solutions.', 'Penalties, noise, data augmentation, and early stopping impose different preferences. The goal is better performance on unseen data, not merely higher training accuracy.', 'Illustrative: L2 coefficient 0.01 adds 0.01 times the squared-weight sum to loss.', 'Normalization: regularization targets generalization; normalization controls activation scale.', '/docs/deep-learning/initialization-regularization-scheduling'),
  t('fine-tuning', 'Fine-tuning', 'Training', 'Fine-tuning continues training a pretrained model on a narrower objective or dataset.', 'Pretraining supplies broad representations, and fine-tuning adapts behavior to a domain or task. Updating all weights costs more memory than parameter-efficient methods.', 'Illustrative: adapt a 7-billion-parameter model on 50,000 instruction-response pairs.', 'Prompting: fine-tuning changes parameters; prompting changes only the request context.', '/docs/interview-prep/llm-serving-and-fine-tuning-questions'),
  t('lora', 'LoRA', 'Training', 'LoRA learns low-rank update matrices while keeping the original model weights frozen.', 'A weight update is represented as the product of two small matrices. This reduces trainable parameters and optimizer state while preserving the base model.', 'Illustrative: a 4,096×4,096 update at rank 16 uses 131,072 trainable values instead of 16,777,216.', 'Adapter layer: LoRA modifies weight updates through low-rank factors; adapters insert new network modules.', '/docs/interview-prep/llm-serving-and-fine-tuning-questions'),
  t('rlhf', 'RLHF', 'Training', 'Reinforcement learning from human feedback optimizes a model using preferences derived from people.', 'A preference model or related signal turns comparisons into a training objective. Policy optimization then shifts outputs toward preferred behavior while constraining drift.', 'Illustrative: reviewers prefer response A in 7 of 10 pairwise comparisons, producing preference data for training.', 'Supervised fine-tuning: SFT imitates target responses; RLHF optimizes a learned preference signal.', '/docs/ai-safety/alignment-and-rlhf'),
  t('distillation', 'Knowledge distillation', 'Training', 'Knowledge distillation trains a smaller student to match signals from a larger teacher.', 'Soft teacher probabilities expose relationships that hard labels omit. The student trades some capacity for lower inference cost.', 'Illustrative: a 1.3B student matches logits from a 7B teacher on 2 million sequences.', 'Quantization: distillation trains another model; quantization stores or computes the same model at lower precision.', '/docs/inference-engineering/quantization-and-compression'),

  t('kv-cache', 'KV cache', 'Inference', 'A KV cache stores attention keys and values from earlier tokens during autoregressive decoding.', 'Without the cache, every new token would recompute projections for the full prefix. The cache saves compute but grows with sequence length, layer count, and key-value width.', 'Illustrative: 32 layers, 32 KV heads, head width 128, 2 bytes, and 2,048 tokens require about 1 GiB.', 'Prefix cache: a KV cache belongs to an active sequence; prefix caching reuses shared prefixes across requests.', '/docs/inference-engineering/roofline-and-kv-cache'),
  t('quantization', 'Quantization', 'Inference', 'Quantization represents model values with fewer bits or a smaller numeric format.', 'Reduced precision lowers memory traffic and can accelerate supported hardware kernels. Calibration and outlier handling determine how much accuracy is retained.', 'Illustrative: 1 billion weights occupy about 2 GB at 16 bits and 0.5 GB at 4 bits, excluding metadata.', 'Pruning: quantization lowers precision; pruning removes weights or structures.', '/docs/inference-engineering/quantization-and-compression'),
  t('continuous-batching', 'Continuous batching', 'Inference', 'Continuous batching admits and removes requests as individual decoding slots become available.', 'Static batches wait for every sequence to finish, wasting capacity on completed rows. Continuous scheduling replaces finished work without draining the whole batch.', 'Illustrative: when 3 of 16 sequences finish, the scheduler admits 3 waiting requests at the next scheduling boundary.', 'Dynamic batching: dynamic batching groups arrivals before execution; continuous batching reschedules during decoding.', '/docs/inference-engineering/continuous-batching-and-speculative-decoding'),
  t('speculative-decoding', 'Speculative decoding', 'Inference', 'Speculative decoding uses a cheaper model to propose tokens that a target model verifies in parallel.', 'Accepted draft tokens advance generation several positions per target-model pass. The method preserves the target distribution when acceptance and correction are implemented correctly.', 'Illustrative: a draft proposes 5 tokens and the target accepts the first 4 before correcting token 5.', 'Distillation: speculative decoding uses two models at runtime; distillation trains a smaller model beforehand.', '/docs/inference-engineering/continuous-batching-and-speculative-decoding'),
  t('time-to-first-token', 'Time to first token', 'Inference', 'Time to first token measures latency from request arrival until the first generated token is available.', 'It includes queueing, prompt processing, and initial sampling. Long prompts can increase it even when later token generation is fast.', 'Illustrative: 35 ms queueing plus 120 ms prefill plus 5 ms sampling gives 160 ms TTFT.', 'Inter-token latency: TTFT covers startup; inter-token latency covers gaps during generation.', '/docs/inference-engineering/overview'),
  t('tokens-per-second', 'Tokens per second', 'Inference', 'Tokens per second measures generation throughput over time.', 'The value must state whether it is per request, per device, or aggregate. Batching can improve aggregate throughput while worsening individual latency.', 'Illustrative: 800 output tokens completed in 10 seconds equals 80 aggregate tokens per second.', 'Requests per second: token throughput counts generated units; request throughput counts completed requests.', '/docs/inference-engineering/overview'),
  t('prefill', 'Prefill', 'Inference', 'Prefill processes all prompt tokens to initialize attention state before decoding.', 'The phase can exploit parallel computation across the prompt. Its workload and bottlenecks differ from one-token-at-a-time decode.', 'Illustrative: a 4,096-token prompt is processed in one prefill phase before token 4,097 is sampled.', 'Decode: prefill processes the prompt in parallel; decode extends the sequence incrementally.', '/docs/inference-engineering/overview'),
  t('decode', 'Decode phase', 'Inference', 'Decode is the autoregressive phase that generates one new token per active sequence per iteration.', 'Each iteration reads model weights and the existing KV cache. It is often memory-bandwidth constrained at small batch sizes.', 'Illustrative: 100 decode iterations produce 100 new tokens for one active sequence.', 'Prefill: decode handles new tokens sequentially; prefill handles the prompt in parallel.', '/docs/inference-engineering/overview'),
  t('tensor-parallelism', 'Tensor parallelism', 'Inference', 'Tensor parallelism splits individual tensor operations across devices.', 'Each device computes a shard of a layer and communicates partial results. It reduces per-device weight memory but introduces collective communication.', 'Illustrative: an 8,192-column matrix is split into four 2,048-column shards across 4 GPUs.', 'Pipeline parallelism: tensor parallelism splits layers internally; pipeline parallelism assigns different layers to stages.', '/docs/mlops/gpu-and-distributed-training'),
  t('model-serving', 'Model serving', 'Inference', 'Model serving exposes a trained model through a reliable runtime interface.', 'A serving system handles request validation, scheduling, execution, observability, and failure recovery. Model quality alone does not provide these operational guarantees.', 'Illustrative: 4 replicas each sustain an illustrative 25 requests per second, giving 100 requests per second before coordination overhead.', 'Deployment: deployment installs a release; serving is the runtime system answering requests.', '/docs/frameworks/serving-mlops'),

  t('retrieval-augmented-generation', 'Retrieval-augmented generation', 'RAG', 'RAG retrieves external evidence and places it in the generation context.', 'Retrieval supplies current or private information without changing model weights. Generation must still connect claims to the retrieved evidence.', 'Illustrative: retrieve 5 passages of 300 tokens each and add 1,500 evidence tokens to the prompt.', 'Fine-tuning: RAG changes context at request time; fine-tuning changes model parameters.', '/docs/llms-genai/rag'),
  t('chunking', 'Chunking', 'RAG', 'Chunking divides source material into units that can be indexed and retrieved.', 'Chunk boundaries control how much context stays together and how precisely retrieval can target it. Overlap can preserve cross-boundary meaning at extra storage and retrieval cost.', 'Illustrative: split 10,000 tokens into 20 chunks of 512 tokens with 12-token overlap adjustments.', 'Tokenization: tokenization creates model units; chunking groups content for retrieval.', '/docs/llms-genai/rag'),
  t('vector-database', 'Vector database', 'RAG', 'A vector database stores embeddings and searches for nearby vectors.', 'It combines an approximate-nearest-neighbor index with metadata, filtering, and persistence. Retrieval quality still depends on embeddings and document preparation.', 'Illustrative: search 10 million 768-dimensional vectors and return the nearest 20 candidates.', 'Relational database: vector search ranks geometric similarity; relational queries match structured predicates and joins.', '/docs/databases/vector/overview'),
  t('cosine-similarity', 'Cosine similarity', 'RAG', 'Cosine similarity measures the angle between two vectors.', 'It compares direction while ignoring overall magnitude. For normalized embeddings, cosine similarity equals their dot product.', 'Illustrative: vectors [1, 0] and [0.8, 0.6] have cosine similarity 0.8.', 'Euclidean distance: cosine compares direction; Euclidean distance measures straight-line separation.', '/docs/nlp/word-embeddings'),
  t('dense-retrieval', 'Dense retrieval', 'RAG', 'Dense retrieval ranks items using learned vector representations.', 'An encoder maps queries and documents into a shared space. Semantic neighbors can match even when they share few exact words.', 'Illustrative: “reset password” retrieves “account credential recovery” at similarity 0.84.', 'Sparse retrieval: dense retrieval uses learned vectors; sparse retrieval relies on term-weighted dimensions.', '/docs/llms-genai/retrieval-and-reranking-architectures'),
  t('bm25', 'BM25', 'RAG', 'BM25 is a sparse ranking function based on term frequency, document frequency, and length normalization.', 'It rewards query terms that are frequent in a document but rare across the collection. Saturation prevents repeated terms from increasing score without bound.', 'Illustrative: a rare term appearing 3 times contributes more than a common term appearing 3 times.', 'TF-IDF: BM25 adds term saturation and tunable document-length normalization.', '/docs/llms-genai/retrieval-and-reranking-architectures'),
  t('hybrid-search', 'Hybrid search', 'RAG', 'Hybrid search combines sparse lexical ranking with dense semantic ranking.', 'The two retrievers capture complementary signals. Score normalization or rank fusion is needed because their raw scores are not directly comparable.', 'Illustrative: reciprocal-rank fusion combines dense rank 2 and BM25 rank 5 for one document.', 'Reranking: hybrid search merges retrievers; reranking applies a later, usually more expensive scorer.', '/docs/llms-genai/retrieval-and-reranking-architectures'),
  t('reranker', 'Reranker', 'RAG', 'A reranker rescoring a small candidate set with a more precise relevance model.', 'First-stage retrieval maximizes recall cheaply, then the reranker spends more compute per candidate. Cross-encoders can inspect query-document interactions directly.', 'Illustrative: retrieve 100 candidates in 20 ms, rerank them, and pass the top 8 to the model.', 'Retriever: a retriever searches the full collection; a reranker refines its shortlist.', '/docs/llms-genai/retrieval-and-reranking-architectures'),
  t('recall-at-k', 'Recall@k', 'RAG', 'Recall@k is the fraction of relevant items found among the top k results.', 'It measures whether retrieval surfaces the needed evidence before generation. Increasing k cannot reduce recall for the same ranking, but it can add distracting context.', 'Illustrative: 4 of 5 relevant passages appear in the top 10, so Recall@10 = 0.80.', 'Precision@k: recall asks how much relevant material was found; precision asks how much retrieved material was relevant.', '/docs/ai-evaluation/llm-rag-agent-evaluation'),
  t('grounding', 'Grounding', 'RAG', 'Grounding ties a generated claim to supplied evidence or an authoritative source.', 'A grounded response should remain within what the evidence supports and make provenance inspectable. Retrieval alone does not guarantee grounding.', 'Illustrative: 6 factual claims are checked and 5 are supported by cited passages.', 'Citation: a citation points to a source; grounding requires the claim to be supported by it.', '/docs/mlops/llm-evaluation-and-ragops'),

  t('ai-agent', 'AI agent', 'Agents', 'An AI agent selects and executes actions toward a goal using observed state.', 'The agent loop connects model decisions to tools and an environment. Reliability depends on state handling, permissions, stopping rules, and verification.', 'Illustrative: inspect 12 files, edit 2, run 3 checks, then stop when all checks pass.', 'Chatbot: a chatbot returns messages; an agent can take consequential actions through tools.', '/docs/agents/agent-fundamentals'),
  t('tool-calling', 'Tool calling', 'Agents', 'Tool calling lets a model request a typed external operation.', 'The model produces a tool name and structured arguments rather than directly performing the operation. The host validates, executes, and returns the result.', 'Illustrative: call weather({city: "Pune"}) and receive temperature 29 °C.', 'Function execution: the model proposes the call; the application actually executes it.', '/docs/agents/agent-fundamentals'),
  t('react-pattern', 'ReAct pattern', 'Agents', 'ReAct alternates model reasoning, actions, and observations in a task loop.', 'Each observation updates the next decision instead of relying on a fixed initial plan. The loop needs a stopping condition and protection against repeated ineffective actions.', 'Illustrative: search once, inspect 3 results, calculate 2 values, then answer.', 'Chain of thought: ReAct couples reasoning to external actions; chain of thought alone may remain internal text.', '/docs/agents/react-agent-production'),
  t('planning-agent', 'Planning agent', 'Agents', 'A planning agent decomposes a goal into coordinated steps before or during execution.', 'Plans expose dependencies and checkpoints that a single reactive step can miss. Useful agents revise plans when observations invalidate assumptions.', 'Illustrative: a 5-step plan marks step 3 blocked, completes step 4 independently, then retries step 3.', 'Workflow: a workflow has predefined transitions; an agent plan can be generated and revised at runtime.', '/docs/agents/plan-and-execute'),
  t('agent-memory', 'Agent memory', 'Agents', 'Agent memory preserves useful state beyond the model’s immediate context.', 'Working memory supports the current run, while persistent memory can survive across sessions. Retrieval and deletion policies matter as much as storage.', 'Illustrative: store 40 task facts, retrieve the top 6 for the next step, and expire 12 after 30 days.', 'Context window: context is what the model sees now; memory is stored state that may be retrieved later.', '/docs/context-engineering/external-memory-and-persistence'),
  t('multi-agent-system', 'Multi-agent system', 'Agents', 'A multi-agent system coordinates multiple decision-making agents around a task.', 'Specialization can separate roles and contexts, but communication adds latency and failure modes. More agents do not automatically improve the result.', 'Illustrative: one planner assigns 3 independent checks to 3 workers and merges their evidence.', 'Parallel processing: multiple agents make decisions and communicate; parallel workers may only execute fixed computations.', '/docs/agents/multi-agent-systems'),
  t('supervisor-agent', 'Supervisor agent', 'Agents', 'A supervisor agent routes work, monitors progress, and decides when to stop or escalate.', 'It maintains task-level state while workers focus on bounded subtasks. A poor supervisor can become a bottleneck or hide worker failures.', 'Illustrative: route 8 requests across 3 specialists, retry 1 failure, and escalate 1 ambiguous case.', 'Router: a router selects a destination; a supervisor also tracks execution and outcomes.', '/docs/agents/routing-and-supervisor'),
  t('human-in-the-loop', 'Human in the loop', 'Agents', 'Human in the loop places explicit human judgment inside an automated process.', 'Review points are most valuable where impact or uncertainty is high. The system must present enough evidence for a person to make the decision.', 'Illustrative: auto-approve refunds under $20, but require review at $20 or above.', 'Human on the loop: in-the-loop approval is part of execution; on-the-loop oversight monitors it.', '/docs/ai-safety/scalable-oversight-and-frontier-safety'),
  t('agent-loop', 'Agent loop', 'Agents', 'An agent loop repeatedly observes state, chooses an action, and evaluates the result.', 'The loop converts a one-shot model into a stateful process. Budgets, idempotency, and termination checks prevent uncontrolled repetition.', 'Illustrative: cap execution at 12 turns or $0.50, whichever occurs first.', 'Retry loop: a retry repeats an operation; an agent loop can choose a different action from new evidence.', '/docs/agents/loops-and-graphs'),
  t('agent-harness', 'Agent harness', 'Agents', 'An agent harness is the runtime that supplies tools, state, policy, and verification around a model.', 'The model proposes decisions, while the harness controls what can actually happen. Production behavior depends heavily on this surrounding system.', 'Illustrative: expose 7 allowlisted tools, retain 20 events, and require 4 verification checks before completion.', 'Agent framework: a framework is reusable software; a harness is the concrete runtime configuration and controls.', '/docs/harness-engineering/harness-architecture'),

  t('http', 'HTTP', 'Protocols', 'HTTP is a request-response application protocol for transferring representations and commands.', 'A client sends a method, target, headers, and optional body. A server returns a status, headers, and optional body.', 'Illustrative: GET /models returns status 200 and a 12 KB JSON body.', 'TCP: HTTP defines application messages; TCP transports an ordered byte stream.', '/docs/cs-fundamentals/apis-http-and-protocols'),
  t('rest', 'REST', 'Protocols', 'REST is an architectural style that models operations around resources and uniform interfaces.', 'HTTP APIs often apply REST constraints through resource URLs, standard methods, and stateless requests. An API can use HTTP without being RESTful.', 'Illustrative: PUT /users/42 replaces user 42, while GET /users/42 reads it.', 'RPC: REST emphasizes resources; RPC emphasizes named procedures or methods.', '/docs/cs-fundamentals/apis-http-and-protocols'),
  t('grpc', 'gRPC', 'Protocols', 'gRPC is a typed remote procedure call system commonly carried over HTTP/2.', 'A schema defines services and messages, then tooling generates clients and servers. Streaming and compact binary serialization suit service-to-service communication.', 'Illustrative: StreamTokens returns 50 protobuf messages over one server-streaming call.', 'REST: gRPC exposes typed procedures; REST usually exposes resource-oriented HTTP operations.', '/docs/cs-fundamentals/apis-http-and-protocols'),
  t('websocket', 'WebSocket', 'Protocols', 'WebSocket provides a persistent full-duplex message channel between two peers.', 'After an HTTP upgrade, either side can send frames without opening a new request. Applications must define message semantics and reconnection behavior.', 'Illustrative: one connection carries 200 token events and 4 control messages.', 'Server-sent events: WebSocket is bidirectional; SSE streams only from server to client.', '/docs/cs-fundamentals/apis-http-and-protocols'),
  t('server-sent-events', 'Server-sent events', 'Protocols', 'Server-sent events stream text events from an HTTP server to a client.', 'The browser keeps one response open and processes event frames as they arrive. The channel is one-way, so client commands use separate requests.', 'Illustrative: stream 80 generated-token events followed by one done event.', 'WebSocket: SSE is server-to-client over HTTP; WebSocket is bidirectional.', '/docs/cs-fundamentals/apis-http-and-protocols'),
  t('json-schema', 'JSON Schema', 'Protocols', 'JSON Schema describes and validates the structure of JSON values.', 'It can require fields, constrain types, and define nested alternatives. Validation catches malformed tool arguments before execution.', 'Illustrative: require city as a string and days as an integer from 1 through 10.', 'TypeScript type: JSON Schema validates runtime data; a TypeScript type is erased at runtime.', '/docs/agents/mcp/protocol-deep-dive'),
  t('mcp', 'Model Context Protocol', 'Protocols', 'MCP standardizes how model applications discover and invoke external tools and resources.', 'A client connects to a server, negotiates capabilities, lists available primitives, and sends typed requests. The protocol separates model hosts from integration implementations.', 'Illustrative: initialize once, list 12 tools, then call read_resource with one JSON argument object.', 'Tool calling: tool calling is a model behavior; MCP is a transport and capability protocol around integrations.', '/docs/agents/mcp/protocol-deep-dive'),
  t('a2a', 'Agent2Agent protocol', 'Protocols', 'A2A defines communication patterns for agents that delegate and exchange task state.', 'It gives independent agent systems a shared way to advertise capabilities and manage tasks. It does not prescribe each agent’s internal reasoning loop.', 'Illustrative: a client sends one task, receives 3 status updates, then obtains one artifact.', 'MCP: A2A coordinates agents and tasks; MCP connects applications to tools and resources.', '/docs/agents/a2a/overview'),
  t('idempotency', 'Idempotency', 'Protocols', 'An idempotent operation has the same intended effect when repeated with the same input.', 'Retries are safer when duplicate requests do not duplicate side effects. Idempotency keys let servers recognize repeated submissions.', 'Illustrative: retry payment key abc123 three times but create exactly one $25 charge.', 'Deduplication: idempotency is an operation guarantee; deduplication is one technique used to provide it.', '/docs/cs-fundamentals/apis-http-and-protocols'),
  t('rate-limit', 'Rate limit', 'Protocols', 'A rate limit bounds how many operations a caller may perform in a time interval.', 'Limits protect capacity and distribute access among clients. Responses should communicate remaining quota and retry timing.', 'Illustrative: allow 60 requests per minute and return 429 on request 61.', 'Concurrency limit: a rate limit counts operations over time; a concurrency limit bounds simultaneous work.', '/docs/cs-fundamentals/apis-http-and-protocols'),

  t('accuracy', 'Accuracy', 'Evaluation', 'Accuracy is the fraction of predictions that are correct.', 'It treats every evaluated example as one equal decision. On imbalanced data, high accuracy can hide failure on a rare class.', 'Illustrative: 920 correct predictions among 1,000 examples give accuracy 0.92.', 'Precision: accuracy covers all predictions; precision focuses on predicted positives.', '/docs/ai-evaluation/evaluation-fundamentals'),
  t('precision', 'Precision', 'Evaluation', 'Precision is the fraction of predicted positives that are truly positive.', 'It answers how often a positive alert is correct. Precision matters when false positives are costly.', 'Illustrative: 72 true positives and 18 false positives give precision 72/90 = 0.80.', 'Recall: precision conditions on predictions; recall conditions on actual positives.', '/docs/ai-evaluation/evaluation-fundamentals'),
  t('recall', 'Recall', 'Evaluation', 'Recall is the fraction of actual positives that the system finds.', 'It answers how much of the positive class was recovered. Recall matters when missed positives are costly.', 'Illustrative: 72 true positives and 8 false negatives give recall 72/80 = 0.90.', 'Precision: recall measures coverage of positives; precision measures purity of positive predictions.', '/docs/ai-evaluation/evaluation-fundamentals'),
  t('f1-score', 'F1 score', 'Evaluation', 'F1 is the harmonic mean of precision and recall.', 'The harmonic mean is low when either component is low. F1 ignores true negatives, so its suitability depends on the task.', 'Illustrative: precision 0.80 and recall 0.90 give F1 ≈ 0.847.', 'Accuracy: F1 summarizes positive-class precision and recall; accuracy counts all correct decisions.', '/docs/ai-evaluation/evaluation-fundamentals'),
  t('confusion-matrix', 'Confusion matrix', 'Evaluation', 'A confusion matrix counts predictions by actual and predicted class.', 'Its cells expose which classes are confused rather than collapsing performance into one number. Binary matrices contain true positives, false positives, false negatives, and true negatives.', 'Illustrative: [[TN 900, FP 20], [FN 30, TP 50]] over 1,000 examples.', 'Contingency table: a confusion matrix specifically crosses predicted and actual classes.', '/docs/ai-evaluation/evaluation-fundamentals'),
  t('roc-auc', 'ROC AUC', 'Evaluation', 'ROC AUC measures ranking quality across classification thresholds using true-positive and false-positive rates.', 'It equals the probability that a random positive receives a higher score than a random negative under standard assumptions. It can look optimistic on highly imbalanced problems.', 'Illustrative: an illustrative ROC curve has AUC 0.87 across all thresholds.', 'PR AUC: ROC uses false-positive rate; PR uses precision and recall and is often more revealing for rare positives.', '/docs/ai-evaluation/evaluation-fundamentals'),
  t('calibration', 'Calibration', 'Evaluation', 'Calibration measures whether predicted probabilities match observed frequencies.', 'Among cases assigned probability 0.8, about 80 percent should occur in a calibrated system. A model can rank well while giving poorly calibrated probabilities.', 'Illustrative: of 100 cases scored near 0.7, 68 are positive.', 'Accuracy: calibration evaluates probability reliability; accuracy evaluates final decisions.', '/docs/ai-evaluation/evaluation-fundamentals'),
  t('benchmark', 'Benchmark', 'Evaluation', 'A benchmark is a specified dataset, protocol, and metric used for comparison.', 'Meaningful comparisons require the same version, prompt policy, scoring rules, and contamination controls. A score without its protocol is incomplete.', 'Illustrative: evaluate 2,000 fixed items with exact-match scoring and report 1,540 correct.', 'Evaluation: a benchmark is a standardized evaluation instance; evaluation is the broader measurement process.', '/docs/ai-evaluation/overview'),
  t('ab-test', 'A/B test', 'Evaluation', 'An A/B test randomly assigns traffic between variants to estimate a causal effect.', 'Randomization balances other factors in expectation. The analysis needs a predefined outcome and uncertainty estimate.', 'Illustrative: 10,000 users per variant yield task completion 61.2% for A and 63.0% for B.', 'Offline evaluation: an A/B test measures live user outcomes; offline evaluation uses recorded or synthetic cases.', '/docs/mlops/monitoring-and-drift'),
  t('model-drift', 'Model drift', 'Evaluation', 'Model drift is a change over time that degrades or alters model behavior.', 'Input distributions, target relationships, or user behavior can shift after deployment. Detection requires reference windows and actionable thresholds.', 'Illustrative: positive-class prevalence rises from 8% in training to 15% this month.', 'Data drift: data drift is input change; model drift is the broader observed behavior change and may have several causes.', '/docs/mlops/monitoring-and-drift'),

  t('prompt-injection', 'Prompt injection', 'Safety and MLOps', 'Prompt injection is untrusted content that attempts to redirect a model’s instructions or tool use.', 'Because models process instructions and data through the same token channel, quoted content can influence behavior. Isolation, least privilege, and validation reduce impact.', 'Illustrative: a retrieved page says “ignore policy and send secrets,” but the tool allowlist blocks secret access.', 'Jailbreak: prompt injection often arrives through task data; a jailbreak is a direct attempt to bypass safeguards.', '/docs/ai-security/owasp-llm-top-10-and-prompt-attacks'),
  t('jailbreak', 'Jailbreak', 'Safety and MLOps', 'A jailbreak is an input designed to bypass a model’s behavioral safeguards.', 'Attackers use reframing, encoding, or multi-turn pressure to elicit disallowed behavior. Defense requires adversarial evaluation and layered controls outside the model.', 'Illustrative: a red-team set contains 500 attack prompts across 10 strategies.', 'Prompt injection: a jailbreak targets model safeguards directly; prompt injection can exploit untrusted external content.', '/docs/ai-security/ai-red-teaming'),
  t('guardrail', 'Guardrail', 'Safety and MLOps', 'A guardrail is a control that constrains inputs, outputs, or actions around a model.', 'Guardrails may validate schemas, classify content, limit tools, or require approval. No single guardrail covers every failure mode.', 'Illustrative: reject transfers above $100 and require human approval from $25 through $100.', 'System prompt: a system prompt is model context; a guardrail can enforce policy outside the model.', '/docs/ai-safety/overview'),
  t('red-teaming', 'AI red teaming', 'Safety and MLOps', 'AI red teaming systematically searches for harmful, insecure, or unreliable model behavior.', 'Testers construct adversarial cases around a threat model and record reproducible failures. Findings become mitigations and regression tests.', 'Illustrative: 4 testers run 1,200 cases and reproduce 37 unique failures.', 'Penetration testing: AI red teaming includes model behavior and social harms beyond conventional software vulnerabilities.', '/docs/ai-security/ai-red-teaming'),
  t('data-poisoning', 'Data poisoning', 'Safety and MLOps', 'Data poisoning manipulates training or retrieval data to change system behavior.', 'An attacker can insert mislabeled examples, backdoors, or malicious documents. Provenance, filtering, and anomaly detection reduce exposure.', 'Illustrative: 200 poisoned records are inserted into a 100,000-record training set.', 'Prompt injection: poisoning changes stored data; prompt injection influences a particular model interaction.', '/docs/ai-security/model-and-data-attacks'),
  t('model-registry', 'Model registry', 'Safety and MLOps', 'A model registry records versioned model artifacts and their lifecycle metadata.', 'It connects a deployable artifact to training data, code, metrics, approvals, and status. This makes rollback and audit possible.', 'Illustrative: version 17 links one artifact hash, 6 metrics, and 2 approval records.', 'Artifact store: an artifact store holds files; a registry adds identity, metadata, stages, and lineage.', '/docs/mlops/feature-stores-and-model-registry'),
  t('feature-store', 'Feature store', 'Safety and MLOps', 'A feature store manages reusable feature definitions and values for training and serving.', 'Shared definitions reduce training-serving skew. Point-in-time retrieval prevents future information from leaking into historical examples.', 'Illustrative: serve 120 features under 15 ms and reconstruct their values as of 2026-01-15.', 'Data warehouse: a warehouse stores analytical data broadly; a feature store specializes in model-ready features and serving consistency.', '/docs/mlops/feature-stores-and-model-registry'),
  t('experiment-tracking', 'Experiment tracking', 'Safety and MLOps', 'Experiment tracking records configurations, artifacts, and results for model runs.', 'A run becomes reproducible only when code, data version, environment, and parameters are connected. Comparing runs then reveals which change caused a metric shift.', 'Illustrative: compare 24 runs across 3 learning rates and 2 batch sizes with 4 random seeds.', 'Observability: experiment tracking covers development runs; observability monitors deployed systems.', '/docs/mlops/experiment-tracking'),
  t('canary-deployment', 'Canary deployment', 'Safety and MLOps', 'A canary deployment sends a small share of production traffic to a new version before wider rollout.', 'The limited exposure bounds damage while live metrics are compared. Automated rollback should use predefined safety and quality thresholds.', 'Illustrative: route 5% of requests to version B for 30 minutes, then expand to 25% if error rate stays below 1%.', 'A/B test: a canary primarily manages release risk; an A/B test estimates a product effect.', '/docs/mlops/deployment-strategies'),
  t('model-monitoring', 'Model monitoring', 'Safety and MLOps', 'Model monitoring measures deployed model inputs, outputs, quality, latency, and failures over time.', 'Operational metrics show whether the service works, while statistical and outcome metrics show whether the model remains useful. Alerts need owners and response procedures.', 'Illustrative: alert when p95 latency exceeds 800 ms for 10 minutes or null outputs exceed 0.5%.', 'Logging: logging records events; monitoring aggregates signals and triggers action.', '/docs/mlops/monitoring-and-drift'),
];

export const glossaryBySlug = new Map(glossaryTerms.map((entry) => [entry.slug, entry]));
